const fontFix=document.createElement('style');fontFix.textContent=`:root{--blue:#054ca1!important;--navy:#062f66!important}html,body,button,input,select,textarea,a,h1,h2,h3,h4,p,small,span,label{font-family:'Segoe UI',Arial,sans-serif!important;font-style:normal}.btn,.save-btn,.secondary-btn{font:700 11px 'Segoe UI',Arial,sans-serif!important}.admin-brand img{width:195px!important;height:70px!important;object-fit:contain!important;object-position:center!important;display:block!important}`;document.head.append(fontFix);document.querySelectorAll('.admin-brand img').forEach(img=>{img.src='assets/wcs-logo-transparent.png';img.alt='WEST CRANE SERVICE'});
