let data=JSON.parse(localStorage.getItem('wcs-admin-data')||'null')||seed;const contactDefaults={phone:'+7‒778‒214‒86‒04',whatsapp:'+7‒778‒214‒86‒04',address:{ru:'Казахстан, город Атырау, улица Сабыр Ержанов, 43',kz:'Қазақстан Республикасы, Атырау қаласы, Сабыр Ержанов көшесі, 43',en:'43 Sabyr Yerzhanov Street, Atyrau, Kazakhstan'}};if(localStorage.getItem('wcs-contact-v3')!=='1'){data.contacts={...data.contacts,...contactDefaults};localStorage.setItem('wcs-admin-data',JSON.stringify(data));localStorage.setItem('wcs-contact-v3','1')}const licenceV4={id:'licence-1',name:{ru:'Аттестат на право проведения работ в области промышленной безопасности',kz:'Өнеркәсіптік қауіпсіздік саласындағы жұмыстарды жүргізу құқығына берілген аттестат',en:'Certificate Authorizing the Performance of Industrial Safety Works'},type:'PDF',meta:'PDF · 301.0 KB',file:'assets/KZ37VEK00018011_ru.pdf',fileName:'KZ37VEK00018011_ru.pdf',mime:'application/pdf'};if(localStorage.getItem('wcs-licence-v4')!=='1'){data.documents=[licenceV4];localStorage.setItem('wcs-admin-data',JSON.stringify(data));localStorage.setItem('wcs-licence-v4','1')}let selectedCourse=null,selectedDocument=null,pendingCourseImage='',pendingDocumentFile='';
function save(){localStorage.setItem('wcs-admin-data',JSON.stringify(data));const s=document.querySelector('#saved-state');s.textContent='Сохранено только что';setTimeout(()=>s.textContent='Все изменения сохранены',1800)}
function pathGet(path){return path.split('.').reduce((o,k)=>o?.[k],data)}function pathSet(path,value){const keys=path.split('.');let o=data;keys.slice(0,-1).forEach(k=>o=o[k]);o[keys.at(-1)]=value}
function fillFields(prefix=''){document.querySelectorAll('[data-field]').forEach(el=>{const p=el.dataset.field;if(p.startsWith('course.')||p.startsWith('document.'))return;const value=pathGet(p);if(value!==undefined){if(el.type==='checkbox')el.checked=!!value;else el.value=value}})}
function clearForm(prefix){document.querySelectorAll(`[data-field^="${prefix}."]`).forEach(el=>{if(el.type==='checkbox')el.checked=false;else el.value=''})}
function editCourse(course){selectedCourse=course;document.querySelector('#course-form-title').textContent=course?'Редактировать курс':'Новый курс';document.querySelectorAll('[data-field^="course."]').forEach(el=>{const key=el.dataset.field.replace('course.','');const value=key.split('.').reduce((o,k)=>o?.[k],course||{});if(el.type==='checkbox')el.checked=!!value;else el.value=value||''});document.querySelector('#course-image-name').textContent=course?.image||'PNG, JPG до 10 MB'}
function renderCourses(){const list=document.querySelector('#course-list');list.innerHTML=data.courses.map(c=>`<button class="item-card ${selectedCourse?.id===c.id?'selected':''}" data-course-id="${c.id}"><span class="item-thumb" style="background-image:url('${c.image||'assets/course-safety.png'}')"></span><span><b>${c.name.ru}</b><small>${c.published?'Опубликован':'Черновик'} · ${c.format}</small></span><i>→</i></button>`).join('');document.querySelector('#course-count').textContent=data.courses.length;document.querySelector('#metric-courses').textContent=data.courses.filter(c=>c.published).length;list.querySelectorAll('[data-course-id]').forEach(b=>b.addEventListener('click',()=>{selectedCourse=data.courses.find(c=>c.id===b.dataset.courseId);editCourse(selectedCourse);renderCourses()}))}
function editDocument(doc){selectedDocument=doc;document.querySelectorAll('[data-field^="document."]').forEach(el=>{const key=el.dataset.field.replace('document.','');const value=key.split('.').reduce((o,k)=>o?.[k],doc||{});el.value=value||''});document.querySelector('#document-file-name').textContent=doc?.file||'Выберите файл для прикрепления'}
function renderDocuments(){const list=document.querySelector('#document-list');list.innerHTML=data.documents.map(d=>`<button class="item-card ${selectedDocument?.id===d.id?'selected':''}" data-document-id="${d.id}"><span class="doc-icon">${d.type?.slice(0,3).toUpperCase()||'PDF'}</span><span><b>${d.name.ru}</b><small>${d.meta||'Файл не прикреплён'}</small></span><i>→</i></button>`).join('');document.querySelector('#doc-count').textContent=data.documents.length;document.querySelector('#metric-docs').textContent=data.documents.length;list.querySelectorAll('[data-document-id]').forEach(b=>b.addEventListener('click',()=>{selectedDocument=data.documents.find(d=>d.id===b.dataset.documentId);editDocument(selectedDocument);renderDocuments()}))}
function showView(view){document.querySelectorAll('.admin-view').forEach(p=>p.classList.toggle('active',p.dataset.panel===view));document.querySelectorAll('.side-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={overview:'Обзор',home:'Главная',courses:'Курсы',about:'О компании',documents:'Документы',corporate:'Корпоративное обучение',contacts:'Контакты',requests:'Заявки'};document.querySelector('#view-title').textContent=titles[view];if(view==='courses')renderCourses();if(view==='documents')renderDocuments();}
function saveSection(section){const fields=document.querySelectorAll(`[data-field^="${section}."]`);fields.forEach(el=>pathSet(el.dataset.field,el.type==='checkbox'?el.checked:el.value));save();if(section==='home')document.querySelector('[data-save="home"]').textContent='Сохранено ✓'}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){showView(view.dataset.view);return}});
document.querySelector('#login-form').addEventListener('submit',e=>{e.preventDefault();if(document.querySelector('#login-name').value==='admin'&&document.querySelector('#login-password').value==='WCS2024!'){sessionStorage.setItem('wcs-admin','1');login.style.display='none';dashboard.style.display='grid';fillFields();renderCourses();renderDocuments()}else alert('Неверный логин или пароль')});
if(sessionStorage.getItem('wcs-admin')==='1'){login.style.display='none';dashboard.style.display='grid';fillFields();renderCourses();renderDocuments()}
document.querySelector('#logout').addEventListener('click',()=>{sessionStorage.removeItem('wcs-admin');location.reload()});
document.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',()=>saveSection(b.dataset.save)));
document.querySelector('#new-course').addEventListener('click',()=>{selectedCourse=null;editCourse(null);showView('courses')});
document.querySelector('#save-course').addEventListener('click',()=>{const c=selectedCourse||{id:Date.now().toString(),name:{},desc:{}};document.querySelectorAll('[data-field^="course."]').forEach(el=>{const key=el.dataset.field.replace('course.','').split('.');let o=c;key.slice(0,-1).forEach(k=>{o[k]??={};o=o[k]});o[key.at(-1)]=el.type==='checkbox'?el.checked:el.value});if(pendingCourseImage)c.image=pendingCourseImage;if(!selectedCourse)data.courses.push(c);save();selectedCourse=c;pendingCourseImage='';renderCourses();alert('Курс сохранён')});
document.querySelector('#delete-course').addEventListener('click',()=>{if(!selectedCourse)return;if(confirm('Удалить этот курс?')){data.courses=data.courses.filter(c=>c.id!==selectedCourse.id);selectedCourse=null;save();renderCourses();editCourse(null)}});
document.querySelector('#course-image').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;document.querySelector('#course-image-name').textContent=file.name;const reader=new FileReader();reader.onload=()=>pendingCourseImage=reader.result;reader.readAsDataURL(file)});
document.querySelector('#new-document').addEventListener('click',()=>{selectedDocument=null;editDocument(null);showView('documents')});
document.querySelector('#save-document').addEventListener('click',()=>{const d=selectedDocument||{id:Date.now().toString(),name:{}};document.querySelectorAll('[data-field^="document."]').forEach(el=>{const key=el.dataset.field.replace('document.','').split('.');let o=d;key.slice(0,-1).forEach(k=>{o[k]??={};o=o[k]});o[key.at(-1)]=el.value});if(pendingDocumentFile)d.file=pendingDocumentFile;if(!selectedDocument)data.documents.push(d);save();selectedDocument=d;pendingDocumentFile='';renderDocuments();alert('Документ сохранён')});
document.querySelector('#delete-document').addEventListener('click',()=>{if(!selectedDocument)return;if(confirm('Удалить этот документ?')){data.documents=data.documents.filter(d=>d.id!==selectedDocument.id);selectedDocument=null;save();renderDocuments();editDocument(null)}});
document.querySelector('#document-file').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;document.querySelector('#document-file-name').textContent=file.name;const reader=new FileReader();reader.onload=()=>pendingDocumentFile=reader.result;reader.readAsDataURL(file)});
const currentAdminYear='2026';document.querySelector('#login-form small').textContent='Демо-доступ: admin / WCS'+currentAdminYear+'!';document.querySelector('#login-form').addEventListener('submit',e=>{if(document.querySelector('#login-password').value==='WCS'+currentAdminYear+'!'){e.preventDefault();e.stopImmediatePropagation();sessionStorage.setItem('wcs-admin','1');login.style.display='none';dashboard.style.display='grid';fillFields();renderCourses();renderDocuments()}},true);
document.querySelector('#login-form').addEventListener('submit',e=>{if(document.querySelector('#login-password').value!=='WCS'+currentAdminYear+'!'){e.preventDefault();e.stopImmediatePropagation();alert('Неверный логин или пароль')}},true);
if(data.contacts){['address','cities'].forEach(key=>{const value=data.contacts[key];if(typeof value!=='object')data.contacts[key]={ru:value||'',kz:value||'',en:value||''}});document.querySelectorAll('[data-field="contacts.address"],[data-field="contacts.cities"]').forEach(el=>el.closest('label')?.remove());const contactsEditor=document.querySelector('[data-panel="contacts"] .editor-card');if(contactsEditor){const languageFields=document.createElement('div');languageFields.className='contacts-language-fields';languageFields.innerHTML='<h3>Адрес и города на трёх языках</h3><div class="language-columns"><label>Адрес · RU<input data-field="contacts.address.ru"></label><label>Мекенжай · KZ<input data-field="contacts.address.kz"></label><label>Address · EN<input data-field="contacts.address.en"></label><label>Города · RU<input data-field="contacts.cities.ru"></label><label>Қалалар · KZ<input data-field="contacts.cities.kz"></label><label>Cities · EN<input data-field="contacts.cities.en"></label></div>';contactsEditor.insertBefore(languageFields,contactsEditor.querySelector('.map-placeholder'));}}fillFields();document.addEventListener('click',event=>{if(event.target.closest('[data-save="contacts"]')||event.target.closest('#save-course')||event.target.closest('#save-document')){setTimeout(()=>{const state=document.querySelector('#saved-state');if(state)state.textContent='Изменения сохранены ✓';const button=event.target.closest('button');if(button&&button.matches('[data-save="contacts"]')){const old=button.innerHTML;button.textContent='Сохранено ✓';setTimeout(()=>button.innerHTML=old,1800)}},0)}});
const homeEditor=document.querySelector('[data-panel="home"] .editor-card');if(homeEditor&&!document.querySelector('#home-hero-image')){const imageField=document.createElement('label');imageField.className='upload-field home-hero-upload';imageField.innerHTML='<span>Главное фото</span><input type="file" id="home-hero-image" accept="image/jpeg,image/png,image/webp"><small>Рекомендуемый размер: 1920 × 900 px · JPG, PNG или WebP до 10 MB</small>';homeEditor.append(imageField);const homeImageInput=imageField.querySelector('input');homeImageInput.addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;if(file.size>10*1024*1024){alert('Файл не должен превышать 10 MB');homeImageInput.value='';return}const reader=new FileReader();reader.onload=()=>{data.home.image=reader.result;imageField.querySelector('small').textContent=`Выбрано: ${file.name} · Рекомендуемый размер: 1920 × 900 px`;};reader.readAsDataURL(file)});if(data.home.image)imageField.querySelector('small').textContent='Текущее изображение загружено · Рекомендуемый размер: 1920 × 900 px'}document.querySelector('[data-save="home"]')?.addEventListener('click',()=>{setTimeout(()=>{save();const state=document.querySelector('#saved-state');if(state)state.textContent='Главное фото и текст сохранены ✓'},0)});
const formatAttachmentSize=bytes=>{if(bytes<1024)return `${bytes} B`;if(bytes<1024*1024)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1024/1024).toFixed(2)} MB`};const attachmentType=file=>{const ext=file.name.split('.').pop()?.toUpperCase()||'FILE';if(file.type==='application/pdf'||ext==='PDF')return 'PDF';if(file.type.startsWith('image/')||['JPG','JPEG','PNG','WEBP'].includes(ext))return ext==='JPEG'?'JPG':ext;return file.type.split('/').pop()?.toUpperCase()||ext};function addAttachmentRemove(input,clear){const wrap=input.closest('.upload-field');if(!wrap||wrap.querySelector('.attachment-remove'))return;const button=document.createElement('button');button.type='button';button.className='attachment-remove';button.textContent='Удалить прикреплённый файл';button.addEventListener('click',()=>{input.value='';clear();const label=wrap.querySelector('small');if(label)label.textContent='Файл удалён. Можно выбрать новый файл.'});wrap.append(button)}const documentInput=document.querySelector('#document-file');if(documentInput){addAttachmentRemove(documentInput,()=>{pendingDocumentFile='';if(selectedDocument)selectedDocument.file='';const type=document.querySelector('[data-field="document.type"]');const meta=document.querySelector('[data-field="document.meta"]');if(type)type.value='';if(meta)meta.value='' });documentInput.addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;const type=attachmentType(file),size=formatAttachmentSize(file.size);const typeField=document.querySelector('[data-field="document.type"]'),metaField=document.querySelector('[data-field="document.meta"]');if(typeField)typeField.value=type;if(metaField)metaField.value=`${type} · ${size}`;const label=document.querySelector('#document-file-name');if(label)label.textContent=`${file.name} · ${type} · ${size}`})}const courseInput=document.querySelector('#course-image');if(courseInput){addAttachmentRemove(courseInput,()=>{pendingCourseImage='';if(selectedCourse)selectedCourse.image='';const label=document.querySelector('#course-image-name');if(label)label.textContent='Изображение удалено. Рекомендуемый размер: 1200 × 800 px'});courseInput.addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;const label=document.querySelector('#course-image-name');if(label)label.textContent=`${file.name} · ${attachmentType(file)} · ${formatAttachmentSize(file.size)}`})}const homeInput=document.querySelector('#home-hero-image');if(homeInput){addAttachmentRemove(homeInput,()=>{if(data.home)data.home.image='';const label=homeInput.closest('.upload-field')?.querySelector('small');if(label)label.textContent='Фото удалено. Рекомендуемый размер: 1920 × 900 px'});homeInput.addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;const label=homeInput.closest('.upload-field')?.querySelector('small');if(label)label.textContent=`${file.name} · ${attachmentType(file)} · ${formatAttachmentSize(file.size)} · Рекомендуемый размер: 1920 × 900 px`})}const attachmentStyle=document.createElement('style');attachmentStyle.textContent='.attachment-remove{display:inline-flex;align-items:center;margin-top:10px;border:1px solid #d6e3f1;background:#fff;color:#b33d52;padding:8px 10px;font:600 10px Segoe UI,Arial,sans-serif;cursor:pointer}.attachment-remove:hover{background:#fff3f5;border-color:#e2a5b2}';document.head.append(attachmentStyle);
const clearRequestsButton=document.querySelector('#clear-requests');if(clearRequestsButton)clearRequestsButton.remove();const requestTable=document.querySelector('.requests-table');const deletedRequests=JSON.parse(localStorage.getItem('wcs-deleted-requests')||'[]');function setupRequestActions(){if(!requestTable)return;const header=requestTable.querySelector('.request-head');if(header&&!header.querySelector('.request-action-head')){const head=document.createElement('span');head.className='request-action-head';head.textContent='Действие';header.append(head)}requestTable.querySelectorAll('.request-row:not(.request-head)').forEach((row,index)=>{const id=row.dataset.requestId||`request-${index}`;row.dataset.requestId=id;if(deletedRequests.includes(id)){row.remove();return}if(row.querySelector('.request-delete'))return;const button=document.createElement('button');button.type='button';button.className='request-delete';button.textContent='Удалить';button.addEventListener('click',()=>{if(!confirm('Удалить эту заявку?'))return;const saved=JSON.parse(localStorage.getItem('wcs-deleted-requests')||'[]');if(!saved.includes(id))saved.push(id);localStorage.setItem('wcs-deleted-requests',JSON.stringify(saved));row.remove();const state=document.querySelector('#saved-state');if(state)state.textContent='Заявка удалена ✓'});row.append(button)})}setupRequestActions();if(requestTable)new MutationObserver(setupRequestActions).observe(requestTable,{childList:true,subtree:true});const requestStyle=document.createElement('style');requestStyle.textContent=`.request-delete{border:1px solid #e2a5b2;background:#fff6f7;color:#b33d52;border-radius:7px;padding:7px 10px;font:600 9px 'Segoe UI',Arial,sans-serif;cursor:pointer}.request-delete:hover{background:#b33d52;color:#fff}.request-row{grid-template-columns:2fr 1.3fr 1fr .7fr auto!important}.request-action-head{color:#8192a6}@media(max-width:650px){.request-row{grid-template-columns:1fr 1fr!important}.request-delete{justify-self:start}}`;document.head.append(requestStyle);
