// Final request renderer: reads the shared envelope and keeps both legacy and
// admin keys synchronized, so old locally saved enquiries remain visible.
function adminReadWcsRequests(){try{const direct=JSON.parse(localStorage.getItem('wcs-requests')||'[]');if(Array.isArray(direct)&&direct.length)return direct;const admin=JSON.parse(localStorage.getItem('wcs-admin-data')||'{}');return Array.isArray(admin.requests)?admin.requests:[]}catch{return[]}}
function adminWriteWcsRequests(requests){localStorage.setItem('wcs-requests',JSON.stringify(requests));try{const admin=JSON.parse(localStorage.getItem('wcs-admin-data')||'{}');admin.requests=requests;localStorage.setItem('wcs-admin-data',JSON.stringify(admin))}catch{}}
function renderWcsRequests(){const table=document.querySelector('.requests-table');if(!table)return;const requests=adminReadWcsRequests();const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));table.innerHTML='<div class="request-row request-head"><span>Клиент</span><span>Курс</span><span>Дата</span><span>Статус</span><span class="request-action-head">Действие</span></div>'+requests.map(r=>`<div class="request-row" data-request-id="${esc(r.id)}"><span><b>${esc(r.name)||'Без имени'}</b><small>${esc(r.phone)}${r.description?` · ${esc(r.description)}`:''}</small></span><span>${esc(r.course)||'Другой запрос'}</span><span>${esc(r.date)}</span><em>${esc(r.status)||'Новая'}</em><button type="button" class="request-delete" data-request-remove="${esc(r.id)}">Удалить</button></div>`).join('');document.querySelectorAll('.side-nav button[data-view="requests"] b').forEach(el=>el.textContent=requests.length)}
