const wcsApiOrigin=location.protocol==='file:'?'https://west-crane-service.pages.dev':'',wcsAdminToken=sessionStorage.getItem('wcs-admin-token')||'';
async function syncWcsRequestsFromApi(){try{if(!wcsAdminToken)return;const response=await fetch(`${wcsApiOrigin}/api/requests?ts=${Date.now()}`,{cache:'no-store',headers:{'x-wcs-admin-token':wcsAdminToken}});if(!response.ok)throw new Error('api unavailable');const data=await response.json();if(Array.isArray(data.requests)){adminWriteWcsRequests(data.requests);renderWcsRequests()}}catch(error){console.warn('WCS requests API unavailable',error)}}
